/**
 * AUTO-GENERATED by AMC preview — do not edit.
 * Regenerated on every preview start. Safe to delete.
 * Placed under the web package so "vite" resolves from this package's node_modules.
 */
import { defineConfig } from "vite";
import path from "node:path";
import { fileURLToPath } from "node:url";

const webRoot = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const previewBase = process.env.AMC_PREVIEW_BASE || "/preview/user-99f863f9eb1d/ox71p-vent-app/";
const baseNorm = previewBase.endsWith("/") ? previewBase : previewBase + "/";

/**
 * Dogfood clones of AMC "develop" often have <BrowserRouter> without basename.
 * Vite `base` alone is not enough: React Router then matches no routes and
 * the preview is a black/empty screen under /preview/u/p/.
 */
function amcBrowserRouterBasename() {
  return {
    name: "amc-browser-router-basename",
    enforce: "pre",
    transform(code, id) {
      if (!id || id.includes("node_modules")) return null;
      if (!/\.(t|j)sx?$/.test(id)) return null;
      if (!code.includes("BrowserRouter")) return null;
      // Already wires basename (current develop_fix / fixed apps).
      if (/BrowserRouter[\s\S]{0,120}basename\s*=/.test(code)) return null;
      const next = code.replace(
        /<BrowserRouter(\s|>)/g,
        "<BrowserRouter basename={(import.meta.env.BASE_URL || \"/\").replace(/\\/+$/, \"\") || undefined}$1"
      );
      return next === code ? null : next;
    },
  };
}

export default defineConfig({
  root: webRoot,
  plugins: [amcBrowserRouterBasename()],
  base: baseNorm,
  resolve: {
    alias: { "@": path.join(webRoot, "src") },
  },
  server: {
    host: process.env.HOST || "127.0.0.1",
    port: Number(process.env.PORT) || 5173,
    strictPort: true,
    allowedHosts: true,
    // Intentionally no proxy: AMC hosts this under /preview/... and tunnels
    // /api when needed. Proxying /preview here loops to a dead host port.
  },
});
